// lifecycle — E3: steps in order with evidence, the installation date after the card (SOP-DEL-04 §1), gates of
// the client's template, and R9 readiness. Generated by `pnpm gen:command`/`gen:query`; acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import {
  aStaffActor,
  countRows,
  createFakeClock,
  createTestDatabase,
  runAsOwner,
  type TestDatabase,
} from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { planInstallation } from '../commands/plan-installation.ts';
import { recordStep } from '../commands/record-step.ts';

const pm = aStaffActor({ roles: ['pm'] });
const clock = createFakeClock(new Date('2026-11-16T09:00:00Z')); // a Monday
let testDb: TestDatabase;
let t: TestKernel;
let siteS: string;
let siteL: string;
const step = (siteId: string, s: string, more: Record<string, unknown> = {}) =>
  t.kernel.execute(recordStep, pm, { siteId, step: s, doneOn: '2026-11-16', ...more }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, recordStep.permission, planInstallation.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Store' };
  ({ id: siteS } = await t.kernel.execute(
    createSite,
    setup,
    { clientId: a.id, ...place, standard: 'S' },
    'test',
  ));
  ({ id: siteL } = await t.kernel.execute(
    createSite,
    setup,
    { clientId: a.id, ...place, standard: 'L' },
    'test',
  ));
  // Gate templates have no command yet (seeded per client); anonymised template with a D−2 readiness check.
  const template = randomUUID();
  await runAsOwner(
    testDb.url,
    `INSERT INTO gate_template (id, client_id, name, gates) VALUES ($1, $2, 'Client A gates', $3)`,
    [
      template,
      a.id,
      JSON.stringify([
        { key: 'g1', name: 'Go/no-go', order: 1 },
        { key: 'g2', name: 'Compliance approved', order: 2 },
        { key: 'g3', name: 'Deployment ready', order: 3, readinessDays: 2 },
      ]),
    ],
  );
  await runAsOwner(testDb.url, `UPDATE site SET gate_template_id = $1 WHERE id = $2`, [template, siteL]);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('lifecycle (E3)', () => {
  it('roles: steps by director, PM, sales; installation plan by director, PM', async () => {
    expect(grantOf(recordStep.permission)?.roles).toEqual(['director', 'pm', 'sales']);
    expect(grantOf(planInstallation.permission)?.roles).toEqual(['director', 'pm']);
    await expect(
      t.kernel.execute(
        recordStep,
        aStaffActor(),
        { siteId: siteS, step: 'card_received', doneOn: '2026-11-16' },
        'test',
      ),
    ).rejects.toBeInstanceOf(Forbidden);
    await expect(step(randomUUID(), 'card_received')).rejects.toBeInstanceOf(NotFound);
  });

  it('SOP-DEL-04 §1: no installation date before the card is complete', async () => {
    await step(siteS, 'card_received');
    await expect(
      t.kernel.execute(planInstallation, pm, { siteId: siteS, date: '2026-11-25' }, 'test'),
    ).rejects.toBeInstanceOf(RuleViolation);
    await step(siteS, 'card_complete');
    await t.kernel.execute(planInstallation, pm, { siteId: siteS, date: '2026-11-25' }, 'test');
    expect(
      await countRows(testDb.url, `site WHERE id = $1 AND planned_installation_date = '2026-11-25'`, [siteS]),
    ).toBe(1);
  });

  it('steps go in order, once; a gate must be in the template; acceptance needs its evidence', async () => {
    await expect(step(siteS, 'installed')).rejects.toBeInstanceOf(RuleViolation);
    await expect(step(siteS, 'card_complete')).rejects.toBeInstanceOf(Conflict);
    await expect(step(siteS, 'g1')).rejects.toBeInstanceOf(RuleViolation);
    for (const s of ['readiness_confirmed', 'go_no_go', 'installed']) await step(siteS, s);
    await expect(step(siteS, 'accepted')).rejects.toBeInstanceOf(RuleViolation);
    await step(siteS, 'accepted', { evidence: '02/Installation Acceptance Form.pdf' });
    expect(await countRows(testDb.url, `site_step WHERE site_id = $1 AND archived_at IS NULL`, [siteS])).toBe(
      6,
    );
  });
});
